SELECT o.channel, CASE WHEN o.channel IN ('mobile', 'store') THEN 'tier_1' ELSE 'other' END AS channel_group, ROUND((100 * SUM(CASE WHEN s.carrier = 'UPS' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_ups FROM shipments s INNER JOIN orders o ON s.order_id = o.id GROUP BY o.channel, CASE WHEN o.channel IN ('mobile', 'store') THEN 'tier_1' ELSE 'other' END ORDER BY pct_ups ASC, channel_group ASC;
